def choose_move(observation):
    # Defensive defaults
    height = observation.get("height", 0)
    width = observation.get("width", 0)

    # Try to infer simple goals from observation keys
    # Resource collection: look for resources and a carrier token
    resources = observation.get("resources", [])
    if not isinstance(resources, list):
        resources = []

    # Territory control: consider owned/neighboring tiles
    owned = observation.get("owned", [])
    if not isinstance(owned, list):
        owned = []

    # Pursuit/evasion: look for opponents and evasion targets
    opponents = observation.get("opponents", [])
    if not isinstance(opponents, list):
        opponents = []

    # Current position
    pos = observation.get("position", {"x": 0, "y": 0})
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    # Helper to clamp within board if size known
    def clamp(v, lo, hi):
        if lo > hi:
            return v
        return max(lo, min(hi, v))

    # Initialize move to stay
    dx = 0
    dy = 0

    # If resources exist, move toward nearest resource if possible (basic heuristic)
    if resources:
        # Find simple target resource at (rx, ry) if coordinates provided
        target = None
        min_dist = None
        for r in resources:
            rx = r.get("x", None)
            ry = r.get("y", None)
            if rx is None or ry is None:
                continue
            dist = abs(rx - x) + abs(ry - y)
            if min_dist is None or dist < min_dist:
                min_dist = dist
                target = (rx, ry)
        if target is not None:
            tx, ty = target
            if tx > x:
                dx = 1
            elif tx < x:
                dx = -1
            else:
                dx = 0
            if ty > y:
                dy = 1
            elif ty < y:
                dy = -1
            else:
                dy = 0
            return [dx, dy]

    # If opponents present, try to move toward center or away defensively
    if opponents:
        # Move away from the closest opponent if possible
        opp = None
        min_dist = None
        for o in opponents:
            ox = o.get("x", None)
            oy = o.get("y", None)
            if ox is None or oy is None:
                continue
            dist = abs(ox - x) + abs(oy - y)
            if min_dist is None or dist < min_dist:
                min_dist = dist
                opp = (ox, oy)
        if opp is not None and min_dist is not None:
            ox, oy = opp
            if ox > x:
                dx = -1
            elif ox < x:
                dx = 1
            else:
                dx = 0
            if oy > y:
                dy = -1
            elif oy < y:
                dy = 1
            else:
                dy = 0
            return [dx, dy]

    # Territory: try to move to improve ownership if possible
    if owned:
        # Prefer moving to adjacent unowned or less-owned tiles if information provided
        # If weights not available, gently randomize by simple heuristic toward (x+1, y)
        if width and height:
            target_x = clamp(x + 1, 0, width - 1)
            target_y = clamp(y, 0, height - 1)
            if target_x != x or target_y != y:
                if target_x > x:
                    dx = 1
                elif target_x < x:
                    dx = -1
                else:
                    dx = 0
                if target_y > y:
                    dy = 1
                elif target_y < y:
                    dy = -1
                else:
                    dy = 0
                return [dx, dy]

    # Default small exploration: move right if possible, else down, else stay
    if width:
        dx = 1 if x + 1 < width else 0
    if height:
        dy = 0 if dy != 0 else (1 if y + 1 < height else 0)

    return [dx, dy]

